static const int STANDARD_JOINT_COUNT = (int)(sizeof(STANDARD_JOINTS) / sizeof(STANDARD_JOINTS[0]));

const StandardSkeleton& StandardSkeleton::get() {
    static const StandardSkeleton skeleton;
    return skeleton;
}

StandardSkeleton::StandardSkeleton() {
    _parents.resize(STANDARD_JOINT_COUNT, -1);
    _boneChildren.resize(STANDARD_JOINT_COUNT, -1);
    for (int i = 0; i < STANDARD_JOINT_COUNT; i++) {
        if (STANDARD_JOINTS[i].parent) {
            _parents[i] = indexOf(STANDARD_JOINTS[i].parent);
        }
    }
    // a bone points at its first child, except where the skeleton branches
    for (int i = 0; i < STANDARD_JOINT_COUNT; i++) {
        int parent = _parents[i];
        if (parent >= 0 && _boneChildren[parent] < 0) {
            _boneChildren[parent] = i;
        }
    }
    _boneChildren[indexOf("Hips")] = indexOf("Spine");
    _boneChildren[indexOf("Spine2")] = indexOf("Neck");
    _boneChildren[indexOf("LeftHand")] = indexOf("LeftHandMiddle1");
    _boneChildren[indexOf("RightHand")] = indexOf("RightHandMiddle1");
}

const TemplateJoint& StandardSkeleton::joint(int index) const {
    return STANDARD_JOINTS[index];
}

int StandardSkeleton::indexOf(const QString& name) const {
    for (int i = 0; i < STANDARD_JOINT_COUNT; i++) {
        if (name == QLatin1String(STANDARD_JOINTS[i].name)) {
            return i;
        }
    }
    return -1;
}
